mapper.select:
SELECT p.id, p.real_name AS name, p.sex, p.age, p.phone, MAX(a.visit_date) as lastVisit FROM sys_patient p LEFT JOIN sys_appointment a ON p.id = a.patient_id WHERE a.doctor_id = #{doctorId}
AND p.real_name LIKE CONCAT('%', #{keyword}, '%')
GROUP BY p.id, p.real_name, p.sex, p.age, p.phone
